const numbers = [1, 2, 3, 4, 5];        // อาร์เรย์ต้นทาง

// รูปแบบ Declarative vs Imperative
// Imperative (for loop): HOW (อย่างไร)
let evens = [];
for (let i = 0; i < numbers.length; i++) {         // วนลูปด้วยตนเอง
  if (numbers[i] % 2 === 0) evens.push(numbers[i]); // ตรวจสอบและรวบรวม
}

// Declarative (higher-order): WHAT (อะไร)
const even = numbers.filter(n => n % 2 === 0);     // filter: เก็บเฉพาะเลขคู่

// การต่อ chain
const result = numbers
  .filter(n => n > 2)             // เก็บเฉพาะตัวเลข > 2
  .map(n => n * 10)               // คูณแต่ละตัวด้วย 10
  .reduce((sum, n) => sum + n, 0); // รวมทั้งหมดเป็นค่าเดียว

// Reduce มีพลังมากที่สุด
const sum = numbers.reduce((a, b) => a + b, 0);     // รวมทุกสมาชิก
const max = numbers.reduce((a, b) => Math.max(a, b)); // หาค่าสูงสุด
const grouped = ['a', 'b', 'a', 'c'].reduce((acc, val) => { // สร้างแผนที่ความถี่
  acc[val] = (acc[val] || 0) + 1;   // เพิ่มจำนวนนับสำหรับแต่ละค่า
  return acc;                        // คืนค่า accumulator
}, {});                              // เริ่มต้นด้วยออบเจกต์ว่าง
console.log(grouped); // { a: 2, b: 1, c: 1 }

