WeakMap และ WeakSet:
const wm = new WeakMap();
let obj = {};
wm.set(obj, 'private data');
console.log(wm.get(obj));  // 'private data'
obj = null;                // obj ถูกลบ, entry ถูกลบอัตโนมัติ

// การประยุกต์ใช้: ข้อมูลส่วนตัวของ instance
const privates = new WeakMap();
class User {
  constructor(name) {
    privates.set(this, { name });
  }
  getName() {
    return privates.get(this).name;
  }
}

// WeakSet — ติดตามออบเจกต์โดยไม่ป้องกัน GC
const visited = new WeakSet();
let node = {};
visited.add(node);
console.log(visited.has(node)); // true

Iterators และ Generators:
// Iterator ที่กำหนดเอง
const range = {
  from: 1, to: 3,
  [Symbol.iterator]() {
    let current = this.from;
    const end = this.to;
    return {
      next() {
        return current <= end
          ? { value: current++, done: false }
          : { done: true };
      }
    };
  }
};
console.log([...range]);  // [1, 2, 3]

// Generator — สิ่งเดียวกัน แต่เขียนง่ายกว่า
function* genRange(start, end) {
  for (let i = start; i <= end; i++) {
    yield i;
  }
}
const gen = genRange(1, 3);
console.log(gen.next());   // { value: 1, done: false }
console.log(gen.next());   // { value: 2, done: false }
console.log(gen.next());   // { value: 3, done: false }
console.log(gen.next());   // { done: true }

// yield* มอบหมายให้ iterable อื่น
function* combine() {
  yield* [1, 2];
  yield* 'ab';
}
console.log([...combine()]); // [1, 2, 'a', 'b']

