// ตัวจัดการคลิกพื้นฐาน
document.querySelector('button').addEventListener('click', (e) => {
  console.log('Clicked:', e.target);
});

// เฟสของอีเวนต์ — อาร์กิวเมนต์ที่สาม
parent.addEventListener('click', () => console.log('capture'), true);  // capture phase
document.addEventListener('click', () => console.log('bubble'));        // bubble phase (ค่าเริ่มต้น)

// Event delegation — ฟังบน parent สำหรับสมาชิกย่อยแบบไดนามิก
ul.addEventListener('click', (e) => {
  if (e.target.matches('li')) {
    console.log('Item clicked:', e.target.textContent);
  }
});

// การป้องกันค่าเริ่มต้น
document.querySelector('form').addEventListener('submit', (e) => {
  e.preventDefault();  // หยุดการส่งฟอร์ม
});
